package cn.xinji.agentplatform.consultation.trademarksearch.adapter.out.dm8;

import cn.xinji.agentplatform.consultation.trademarksearch.application.TrademarkSearchTaskRepository;
import cn.xinji.agentplatform.consultation.trademarksearch.domain.*;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import java.util.function.UnaryOperator;

/** DM8 persistence for synthetic trademark-search task snapshots; the synthetic catalog remains external. */
public final class Dm8TrademarkSearchTaskRepository implements TrademarkSearchTaskRepository {
    private static final String COLUMNS = "task_id,requester_ref,idempotency_key,request_fingerprint,original_name,normalized_name,categories,goods_services,dimensions,statuses,regions,data_sources,page_no,page_size,status,attempt,data_mode,ranking_version,actual_scope,total_candidates,truncated,limitation,error_code,trace_id,row_version,created_at,updated_at";
    private final Supplier<Connection> connections;
    public Dm8TrademarkSearchTaskRepository(Supplier<Connection> connections) { this.connections = connections; }

    @Override public Optional<TrademarkSearchTask> findById(String id) { return one("SELECT " + COLUMNS + " FROM con_trademark_search_task WHERE task_id=?", id); }
    @Override public Optional<TrademarkSearchTask> findByIdempotency(String requester, String key) { return one("SELECT " + COLUMNS + " FROM con_trademark_search_task WHERE requester_ref=? AND idempotency_key=?", requester, key); }
    @Override public List<TrademarkSearchTask> findByRequester(String requester) {
        try (Connection c = connections.get(); PreparedStatement s = c.prepareStatement("SELECT " + COLUMNS + " FROM con_trademark_search_task WHERE requester_ref=? ORDER BY created_at DESC,task_id")) {
            s.setString(1, requester); try (ResultSet rows = s.executeQuery()) { List<TrademarkSearchTask> result = new ArrayList<>(); while (rows.next()) result.add(map(c, rows).task()); return List.copyOf(result); }
        } catch (SQLException e) { throw failure("read history", e); }
    }
    @Override public void save(TrademarkSearchTask task) { transaction("save", c -> { insert(c, task); replaceCandidates(c, task.taskId(), task.candidates()); return null; }); }
    @Override public TrademarkSearchTask update(String id, UnaryOperator<TrademarkSearchTask> operation) {
        return transaction("update", c -> { Versioned value = load(c, id).orElseThrow(() -> new IllegalArgumentException("task not found")); TrademarkSearchTask next = Objects.requireNonNull(operation.apply(value.task()), "updated task"); if (!id.equals(next.taskId())) throw new IllegalArgumentException("task id cannot change"); if (update(c, next, value.version()) != 1) throw new VersionConflictException(id); replaceCandidates(c, id, next.candidates()); return next; });
    }
    @Override public int failInterruptedTasks(Instant now) {
        try (Connection c = connections.get(); PreparedStatement s = c.prepareStatement("UPDATE con_trademark_search_task SET status='FAILED',error_code='RESTART_INTERRUPTED',updated_at=?,row_version=row_version+1 WHERE status IN ('QUEUED','PROCESSING')")) { s.setTimestamp(1, Timestamp.from(now)); return s.executeUpdate(); } catch (SQLException e) { throw failure("recover interrupted tasks", e); }
    }
    private Optional<TrademarkSearchTask> one(String sql, String... values) {
        try (Connection c = connections.get(); PreparedStatement s = c.prepareStatement(sql)) { for (int i=0;i<values.length;i++) s.setString(i+1, values[i]); try (ResultSet rows=s.executeQuery()) { return rows.next()?Optional.of(map(c,rows).task()):Optional.empty(); } } catch(SQLException e){throw failure("read",e);}
    }
    private Optional<Versioned> load(Connection c,String id) throws SQLException { try(PreparedStatement s=c.prepareStatement("SELECT "+COLUMNS+" FROM con_trademark_search_task WHERE task_id=?")){s.setString(1,id);try(ResultSet rows=s.executeQuery()){return rows.next()?Optional.of(map(c,rows)):Optional.empty();}} }
    private Versioned map(Connection c, ResultSet row) throws SQLException {
        String id=row.getString("task_id"); var command=new TrademarkSearchCommand(TrademarkSearchCommand.InputMode.TEXT,row.getString("original_name"),row.getString("normalized_name"),decode(row.getString("categories")),decode(row.getString("goods_services")),decode(row.getString("dimensions")).stream().map(TrademarkSearchCommand.Dimension::valueOf).toList(),new TrademarkSearchCommand.SearchScope(decode(row.getString("statuses")),decode(row.getString("regions")),decode(row.getString("data_sources"))),row.getInt("page_no"),row.getInt("page_size"));
        var task=new TrademarkSearchTask(id,row.getString("requester_ref"),row.getString("idempotency_key"),row.getString("request_fingerprint"),command,TrademarkSearchTask.Status.valueOf(row.getString("status")),row.getInt("attempt"),row.getString("data_mode"),row.getString("ranking_version"),empty(row.getString("actual_scope")),row.getInt("total_candidates"),row.getInt("truncated")!=0,candidates(c,id),empty(row.getString("limitation")),empty(row.getString("error_code")),row.getString("trace_id"),row.getTimestamp("created_at").toInstant(),row.getTimestamp("updated_at").toInstant()); return new Versioned(task,row.getInt("row_version"));
    }
    private static List<TrademarkSearchCandidate> candidates(Connection c,String id) throws SQLException {
        String sql="SELECT candidate_order,source_id,registration_number,name,categories,goods_services,source_status,region,data_source,source_version,source_updated_at,relevance_label FROM con_trademark_search_candidate WHERE task_id=? ORDER BY candidate_order";
        try(PreparedStatement s=c.prepareStatement(sql)){s.setString(1,id);try(ResultSet rows=s.executeQuery()){List<TrademarkSearchCandidate> result=new ArrayList<>();while(rows.next()){int order=rows.getInt(1);result.add(new TrademarkSearchCandidate(rows.getString(2),rows.getString(3),rows.getString(4),decode(rows.getString(5)),decode(rows.getString(6)),rows.getString(7),rows.getString(8),rows.getString(9),rows.getString(10),rows.getString(11),rows.getString(12),dimensions(c,id,order)));}return List.copyOf(result);}}
    }
    private static List<TrademarkSearchCandidate.DimensionResult> dimensions(Connection c,String id,int order) throws SQLException { try(PreparedStatement s=c.prepareStatement("SELECT dimension_name,dimension_state,basis FROM con_trademark_search_dimension WHERE task_id=? AND candidate_order=? ORDER BY dimension_order")){s.setString(1,id);s.setInt(2,order);try(ResultSet rows=s.executeQuery()){List<TrademarkSearchCandidate.DimensionResult> r=new ArrayList<>();while(rows.next())r.add(new TrademarkSearchCandidate.DimensionResult(TrademarkSearchCommand.Dimension.valueOf(rows.getString(1)),TrademarkSearchCandidate.State.valueOf(rows.getString(2)),rows.getString(3)));return List.copyOf(r);}} }
    private static void insert(Connection c,TrademarkSearchTask t)throws SQLException{try(PreparedStatement s=c.prepareStatement("INSERT INTO con_trademark_search_task ("+COLUMNS+") VALUES ("+String.join(",",Collections.nCopies(27,"?"))+")")){bind(s,t,true);s.executeUpdate();}}
    private static int update(Connection c,TrademarkSearchTask t,int version)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE con_trademark_search_task SET requester_ref=?,idempotency_key=?,request_fingerprint=?,original_name=?,normalized_name=?,categories=?,goods_services=?,dimensions=?,statuses=?,regions=?,data_sources=?,page_no=?,page_size=?,status=?,attempt=?,data_mode=?,ranking_version=?,actual_scope=?,total_candidates=?,truncated=?,limitation=?,error_code=?,trace_id=?,created_at=?,updated_at=?,row_version=row_version+1 WHERE task_id=? AND row_version=?")){bind(s,t,false);s.setString(26,t.taskId());s.setInt(27,version);return s.executeUpdate();}}
    private static void bind(PreparedStatement s,TrademarkSearchTask t,boolean insert)throws SQLException{var q=t.inputSnapshot();var scope=q.scope();int i=1;if(insert)s.setString(i++,t.taskId());s.setString(i++,t.requester());s.setString(i++,t.idempotencyKey());s.setString(i++,t.requestFingerprint());s.setString(i++,q.originalName());s.setString(i++,q.normalizedName());s.setString(i++,encode(q.categories()));s.setString(i++,encode(q.goodsServices()));s.setString(i++,encode(q.dimensions().stream().map(Enum::name).toList()));s.setString(i++,encode(scope.statuses()));s.setString(i++,encode(scope.regions()));s.setString(i++,encode(scope.dataSources()));s.setInt(i++,q.page());s.setInt(i++,q.pageSize());s.setString(i++,t.status().name());s.setInt(i++,t.attempt());s.setString(i++,t.dataMode());s.setString(i++,t.rankingVersion());s.setString(i++,t.actualScope());s.setInt(i++,t.totalCandidates());s.setInt(i++,t.truncated()?1:0);s.setString(i++,t.limitation());s.setString(i++,t.errorCode());s.setString(i++,t.traceId());if(insert)s.setInt(i++,0);s.setTimestamp(i++,Timestamp.from(t.createdAt()));s.setTimestamp(i,Timestamp.from(t.updatedAt()));}
    private static void replaceCandidates(Connection c,String id,List<TrademarkSearchCandidate> values)throws SQLException{try(PreparedStatement s=c.prepareStatement("DELETE FROM con_trademark_search_dimension WHERE task_id=?")){s.setString(1,id);s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("DELETE FROM con_trademark_search_candidate WHERE task_id=?")){s.setString(1,id);s.executeUpdate();}try(PreparedStatement candidate=c.prepareStatement("INSERT INTO con_trademark_search_candidate VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)");PreparedStatement dimension=c.prepareStatement("INSERT INTO con_trademark_search_dimension VALUES (?,?,?,?,?,?)")){for(int order=0;order<values.size();order++){var v=values.get(order);int i=1;candidate.setString(i++,id);candidate.setInt(i++,order);candidate.setString(i++,v.sourceId());candidate.setString(i++,empty(v.registrationNumber()));candidate.setString(i++,v.name());candidate.setString(i++,encode(v.categories()));candidate.setString(i++,encode(v.goodsServices()));candidate.setString(i++,v.status());candidate.setString(i++,v.region());candidate.setString(i++,v.dataSource());candidate.setString(i++,v.sourceVersion());candidate.setString(i++,v.updatedAt());candidate.setString(i,v.relevanceLabel());candidate.addBatch();for(int dimensionOrder=0;dimensionOrder<v.dimensions().size();dimensionOrder++){var d=v.dimensions().get(dimensionOrder);dimension.setString(1,id);dimension.setInt(2,order);dimension.setInt(3,dimensionOrder);dimension.setString(4,d.dimension().name());dimension.setString(5,d.state().name());dimension.setString(6,d.basis());dimension.addBatch();}}candidate.executeBatch();dimension.executeBatch();}}
    private <T>T transaction(String action,SqlWork<T> work){try(Connection c=connections.get()){c.setAutoCommit(false);try{T r=work.run(c);c.commit();return r;}catch(SQLException|RuntimeException e){try{c.rollback();}catch(SQLException x){e.addSuppressed(x);}if(e instanceof VersionConflictException||e instanceof IllegalArgumentException)throw (RuntimeException)e;throw failure(action,e);}}catch(SQLException e){throw failure(action,e);}}
    private static String encode(List<String> v){var e=Base64.getUrlEncoder().withoutPadding();return String.join("\n",v.stream().map(x->e.encodeToString(x.getBytes(StandardCharsets.UTF_8))).toList());} private static List<String> decode(String v){if(v==null||v.isBlank())return List.of();var d=Base64.getUrlDecoder();return Arrays.stream(v.split("\\n",-1)).map(x->new String(d.decode(x),StandardCharsets.UTF_8)).toList();} private static String empty(String v){return v==null?"":v;} private static IllegalStateException failure(String a,Exception e){return new IllegalStateException("DM8 trademark search "+a+" failed",e);} private record Versioned(TrademarkSearchTask task,int version){} @FunctionalInterface private interface SqlWork<T>{T run(Connection c)throws SQLException;} public static final class VersionConflictException extends IllegalStateException{public VersionConflictException(String id){super("trademark search task version conflict: "+id);}}
}
